mapper.select:
SELECT id, task_type, document_id, document_line_id, source_location_id, target_location_id, planned_qty,
       completed_qty, state, assignee_id, claim_epoch, action_id, device_command_id, version
FROM outbound_task
WHERE enterprise_id = #{enterpriseId}
  AND warehouse_id = #{warehouseId}
  AND task_type = #{taskType}

    AND id > #{cursor}

ORDER BY id
LIMIT #{limit}
